import math
def gd(eta, steps=200, x=10.0):
    for _ in range(steps): x -= eta*x     # f=0.5x^2, f'=x
    return abs(x)
def adam(eta, steps=200, x=10.0, b1=0.9, b2=0.999, eps=1e-8):
    m = v = 0.0
    for t in range(1, steps+1):
        g = x
        m = b1*m + (1-b1)*g
        v = b2*v + (1-b2)*g*g
        mh = m/(1-b1**t); vh = v/(1-b2**t)
        x -= eta*mh/(math.sqrt(vh)+eps)
    return abs(x)
