import numpy as np
class Counter:
    def __init__(self): self.mul = 0
def attention(X, Wq, Wk, Wv, c):
    n, d = X.shape
    Q, K, V = X@Wq, X@Wk, X@Wv
    S = np.zeros((n,n))
    for i in range(n):
        for j in range(n):
            S[i,j] = float(Q[i]@K[j]); c.mul += d      # QK^T
    S = np.exp(S - S.max(1, keepdims=True)); S /= S.sum(1, keepdims=True)
    O = np.zeros((n,d))
    for i in range(n):
        for j in range(n):
            O[i] += S[i,j]*V[j]; c.mul += d            # (softmax S) V
    return O
rng = np.random.default_rng(0); d = 4
Wq, Wk, Wv = (rng.standard_normal((d,d)) for _ in range(3))
counts = {}
for n in (8, 16, 32):
    c = Counter(); attention(rng.standard_normal((n,d)), Wq, Wk, Wv, c)
    counts[n] = c.mul
exact  = all(counts[n] == 2*n*n*d for n in counts)
quad   = counts[16]/counts[8] == 4 and counts[32]/counts[16] == 4
print(exact and quad)
